$root=dirname(__DIR__,2);$writerPath='app/InstallationProcess/MariaDbEquipmentFacts.php';assertSameValue(true,is_file($root.'/'.$writerPath),'INTENDED_RED sole persistence owner missing');$owned=['fm2_equipment_fact_current','fm2_equipment_fact_history','fm2_equipment_fact_runs','fm2_equipment_fact_sync_metadata','fm2_equipment_fact_diagnostics'];$writer=file_get_contents($root.'/'.$writerPath);foreach($owned as$table)assertSameValue(true,str_contains($writer,$table),'persistence owner owns '.$table);$consumers=['app/InstallationProcess/EquipmentFactsApplication.php','app/InstallationProcess/ErpEquipmentFactsDelivery.php','app/InstallationProcess/NativeErpEquipmentFactsDelivery.php','app/InstallationProcess/MariaDbEquipmentFactsRead.php','app/InstallationProcess/MariaDbYiiObjectCardProjection.php','app/Jobs/MariaDbEquipmentFactsScheduler.php','app/Jobs/JobHandlerRuntime.php','app/Jobs/JobsSchedulerProcess.php','app/Jobs/JobsRuntimeCommand.php','app/YiiRuntime/Commands/ErpEquipmentFactsSyncController.php','app/YiiRuntime/InstallationProcessFactory.php','app/YiiRuntime/Views/object-card.php','config/yii/console.php'];foreach($consumers as$path){$body=@file_get_contents($root.'/'.$path);assertSameValue(true,is_string($body),'INTENDED_RED boundary file missing '.$path);foreach($owned as$table)foreach(['INSERT','UPDATE','DELETE','REPLACE']as$verb)assertSameValue(false,preg_match('/\b'.$verb.'\b[^;]*'.preg_quote($table,'/').'/is',$body)===1,'only persistence owner may '.$verb.' '.$table.' in '.$path);}assertSameValue(true,str_contains(file_get_contents($root.'/app/InstallationProcess/EquipmentFactsApplication.php'),'MariaDbEquipmentFacts'),'public application delegates sole persistence seam');echo"PASS: ERP-EQUIPMENT-FACTS-001 sole writer\n";
